       return {ok:false, msg:'지금 «'+r[0]+'» 입니다. 「점프 — 배송비가 뛰는 지점」을 고르세요.'};
     const L=noteNum(r[1]), R=noteNum(r[2]);
     if(![0,1,2].every(j=>isFinite(got[j]))) return {ok:false, msg:'세 칸을 모두 채우세요.'};
