    <path d="M130.4 150.0 L132.3 146.9 L134.2 143.8 L136.0 140.7 L137.9 137.6 L139.7 134.5 L141.6 131.4 L143.5 128.3 L145.3 125.2 L147.2 122.1 L149.0 119.0 L150.2 115.9 L151.3 112.8 L152.4 109.7 L153.5 106.6 L154.6 103.5 L155.7 100.4 L156.9 97.3 L158.0 94.2 L159.1 91.1 L160.2 88.0 L159.6 84.9 L159.0 81.8 L158.3 78.7 L157.7 75.6 L157.1 72.5 L156.5 69.4 L155.9 66.3 L155.2 63.2 L154.6 60.1 L154.0 57.0 L152.1 53.9 L150.3 50.8 L148.4 47.7 L146.6 44.6 L144.7 41.5 L142.8 38.4 L141.0 35.3 L139.1 32.2 L137.3 29.1 L135.4 26.0" stroke="#111827" stroke-width="2.4" fill="none" stroke-linecap="round" stroke-linejoin="round"/>
